#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────
#
# Mahayuddh: email sending (Gmail SMTP) and email confirmation.
#
# Sends Supabase's auth emails (signup confirmation, password reset) from your
# Gmail through an app password, switches the email templates to the
# /auth/confirm links (they work on any device), turns "Confirm email" ON and
# turns manual identity linking ON. Only those Supabase settings change.
#
# Why confirmation matters: with it off, anyone can sign up with someone
# else's address, and when the real owner later signs in with Google or
# GitHub, Supabase links the two (pre-account takeover).
#
# Run after the email-confirmation PR is deployed: bash scripts/setup-email.sh

umask 077
ENV_FILE="${MAHAYUDDH_OAUTH_ENV:-$HOME/.config/mahayuddh/oauth.env}"
mkdir -p "$(dirname "$ENV_FILE")"

API=""; CALLBACK_URL=""   # set by project_settings in stage 1

for bin in curl python3; do
  command -v "$bin" >/dev/null 2>&1 || { printf 'This wizard needs %s.\n' "$bin"; exit 1; }
done

# need VAR "Prompt": the value comes from the environment if exported, else
# from the saved settings file, else it's asked for. Nothing has a default in
# this script: every project-specific value is yours to provide.
need() {
  local var="$1" prompt="$2"
  if [[ -n "${!var:-}" ]]; then
    note "$var from the environment."
  else
    ask "$var" "$prompt"
  fi
  if [[ -z "${!var:-}" ]]; then warn "$var is required."; exit 1; fi
  write_env "$var" "${!var}"
}

# project_settings: the Supabase project and the site, asked once and saved.
project_settings() {
  need SUPABASE_PROJECT_REF "Supabase project ref (the <ref> in https://<ref>.supabase.co):"
  need SITE_URL "Site URL people sign in on (https://..., no trailing slash):"
  SITE_URL="${SITE_URL%/}"
  write_env SITE_URL "$SITE_URL" >/dev/null
  API="https://api.supabase.com/v1/projects/${SUPABASE_PROJECT_REF}/config/auth"
  CALLBACK_URL="https://${SUPABASE_PROJECT_REF}.supabase.co/auth/v1/callback"
}

# api METHOD [json-file]: token and body travel in files only you can read.
api() {
  local method="$1" body="${2:-}" cfg out code
  cfg=$(mktemp); out=$(mktemp)
  printf 'header = "Authorization: Bearer %s"\nheader = "Content-Type: application/json"\n' \
    "$SUPABASE_ACCESS_TOKEN" > "$cfg"
  if [[ -n "$body" ]]; then
    code=$(curl -sS -K "$cfg" -X "$method" --data-binary "@$body" -o "$out" -w '%{http_code}' "$API" || true)
  else
    code=$(curl -sS -K "$cfg" -X "$method" -o "$out" -w '%{http_code}' "$API" || true)
  fi
  rm -f "$cfg"
  API_STATUS="$code"; API_BODY_FILE="$out"
}

TOTAL_STAGES=4

banner "Mahayuddh · email sending + confirmation"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Supabase project and access token"
project_settings
say ""
say "Reuses the token saved by setup-social-login.sh (Enter keeps it)."
note "New token: https://supabase.com/dashboard/account/tokens"
ask_secret SUPABASE_ACCESS_TOKEN "Supabase access token:"
api GET
if [[ "$API_STATUS" != "200" ]]; then
  warn "Supabase answered HTTP $API_STATUS. Check the token."; rm -f "$API_BODY_FILE"; exit 1
fi
write_env SUPABASE_ACCESS_TOKEN "$SUPABASE_ACCESS_TOKEN"
python3 -I - "$API_BODY_FILE" <<'PY'
import json, sys
c = json.load(open(sys.argv[1]))
print(f"  Email sending (SMTP): {'custom: ' + c['smtp_host'] if c.get('smtp_host') else 'Supabase built-in (a few emails per hour)'}")
print(f"  Confirm email:        {'OFF' if c.get('mailer_autoconfirm') else 'ON'}")
print(f"  Manual linking:       {'ON' if c.get('security_manual_linking_enabled') else 'OFF'}")
PY
rm -f "$API_BODY_FILE"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Gmail app password"
say "Supabase will send as your Gmail address, up to Gmail's ~500 emails a day."
say "An app password is a 16-letter password for one app; your real password"
say "stays private and you can revoke it any time."
warn "App passwords need 2-Step Verification on the Google account."
open_url "https://myaccount.google.com/apppasswords"
step "Sign in if asked. App name: Mahayuddh Supabase → Create."
step "Copy the 16-letter password Google shows (spaces don't matter)."
need SMTP_HOST "SMTP host (for Gmail: smtp.gmail.com):"
need SMTP_PORT "SMTP port (for Gmail: 465):"
need SMTP_SENDER_NAME "Sender name shown in inboxes:"
need SMTP_MAX_PER_HOUR "Max auth emails per hour (Gmail allows ~500/day):"
ask GMAIL_ADDRESS "Address that will send the emails:"
ask_secret GMAIL_APP_PASSWORD "App password:"
GMAIL_APP_PASSWORD="${GMAIL_APP_PASSWORD// /}"
if [[ ${#GMAIL_APP_PASSWORD} -ne 16 ]]; then
  warn "That's ${#GMAIL_APP_PASSWORD} characters; Gmail app passwords are 16. Re-run if it was mistyped."
fi
write_env GMAIL_ADDRESS "$GMAIL_ADDRESS"
write_env GMAIL_APP_PASSWORD "$GMAIL_APP_PASSWORD"
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Apply in Supabase"
say "This sets, and nothing else:"
step "SMTP: $SMTP_HOST:$SMTP_PORT as $GMAIL_ADDRESS, sender name $SMTP_SENDER_NAME, $SMTP_MAX_PER_HOUR emails/hour"
step "Templates: confirmation and password reset link to $SITE_URL/auth/confirm"
step "Confirm email: ON (new email signups must click the link)"
step "Manual identity linking: ON (for 'Connect GitHub' in the profile)"
if confirm "Apply now?"; then
  body=$(mktemp)
  GMAIL_ADDRESS="$GMAIL_ADDRESS" GMAIL_APP_PASSWORD="$GMAIL_APP_PASSWORD" \
  SMTP_HOST="$SMTP_HOST" SMTP_PORT="$SMTP_PORT" SMTP_SENDER_NAME="$SMTP_SENDER_NAME" \
  SMTP_MAX_PER_HOUR="$SMTP_MAX_PER_HOUR" \
  python3 -I - "$body" <<'PY'
import json, os, sys
site = "{{ .SiteURL }}"
# Auth emails as a Mahayuddh Pass: obsidian ticket, gold action, perforated
# stub with the serial lines. Email-client safe: tables, inline styles,
# bgcolor fallbacks, system and mono font stacks, a hidden inbox preheader,
# and the raw link under the button for clients that block it. Links expire
# with mailer_otp_exp (3600s), hence "1 hour".
SANS = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif"
MONO = "ui-monospace,SFMono-Regular,Menlo,Consolas,'Liberation Mono',monospace"
def serial(label, value):
    return f"""<td valign="top" style="padding:0 16px 0 0;font-family:{MONO};font-size:10px;line-height:16px;letter-spacing:0.08em;text-transform:uppercase;color:#84868f">{label}<br><span style="font-size:12px;line-height:18px;letter-spacing:0.06em;color:#ededef">{value}</span></td>"""
def page(preheader, title, intro, cta, href, kind, outro):
    return f"""<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:#0a0b0e">{preheader}&#8199;&#847;&#8199;&#847;&#8199;&#847;&#8199;&#847;&#8199;&#847;&#8199;&#847;</div>
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#0a0b0e" style="background:#0a0b0e">
  <tr><td align="center" style="padding:40px 16px 48px">
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="max-width:520px">
      <tr><td style="padding:0 4px 20px">
        <table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>
          <td valign="middle" style="padding:0 10px 0 0"><img src="{site}/icon-192.png" width="28" height="28" alt="" style="display:block;border:0;border-radius:7px"></td>
          <td valign="middle" style="font-family:{SANS};font-size:16px;font-weight:600;letter-spacing:-0.01em;color:#ededef">Mahayuddh</td>
        </tr></table>
      </td></tr>
      <tr><td bgcolor="#141518" style="background:#141518;border-radius:16px 16px 0 0;border-top:1px solid #2b2c32;padding:32px 32px 28px">
        <h1 style="margin:0 0 12px;font-family:{SANS};font-size:26px;line-height:32px;font-weight:600;letter-spacing:-0.02em;color:#ededef">{title}</h1>
        <p style="margin:0 0 28px;font-family:{SANS};font-size:15px;line-height:24px;color:#a1a3ab">{intro}</p>
        <table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>
          <td bgcolor="#f5b83d" style="background:#f5b83d;border-radius:8px"><a href="{href}" style="display:inline-block;padding:14px 24px;font-family:{SANS};font-size:15px;font-weight:600;line-height:20px;color:#1a1406;text-decoration:none;border-radius:8px">{cta}&nbsp;&rarr;</a></td>
        </tr></table>
        <p style="margin:20px 0 0;font-family:{SANS};font-size:13px;line-height:20px;color:#84868f">The link works once and expires in 1 hour.</p>
      </td></tr>
      <tr><td bgcolor="#141518" style="background:#141518;line-height:0;font-size:0">
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0"><tr>
          <td width="11" height="22" bgcolor="#0a0b0e" style="background:#0a0b0e;border-radius:0 11px 11px 0;font-size:0;line-height:0">&nbsp;</td>
          <td style="padding:0 6px"><div style="border-top:1px dashed #34363d;height:0;line-height:0;font-size:0">&nbsp;</div></td>
          <td width="11" height="22" bgcolor="#0a0b0e" style="background:#0a0b0e;border-radius:11px 0 0 11px;font-size:0;line-height:0">&nbsp;</td>
        </tr></table>
      </td></tr>
      <tr><td bgcolor="#191a1e" style="background:#191a1e;border-radius:0 0 16px 16px;padding:18px 32px 22px">
        <table role="presentation" cellpadding="0" cellspacing="0" border="0"><tr>
          {serial("Type", kind)}{serial("Valid", "1 hour")}{serial("Uses", "Once")}
        </tr></table>
      </td></tr>
      <tr><td style="padding:24px 4px 0;font-family:{SANS};font-size:12px;line-height:18px;color:#84868f">
        Button not working? Paste this link into your browser:<br>
        <a href="{href}" style="color:#a1a3ab;text-decoration:underline;word-break:break-all">{href}</a>
      </td></tr>
      <tr><td style="padding:20px 4px 0;font-family:{SANS};font-size:12px;line-height:18px;color:#84868f">{outro}</td></tr>
      <tr><td style="padding:28px 4px 0;font-family:{SANS};font-size:12px;line-height:18px;color:#55575e">Mahayuddh &middot; Practice DSA with your people &middot; <a href="{site}" style="color:#55575e;text-decoration:underline">mahayuddh.vercel.app</a></td></tr>
    </table>
  </td></tr>
</table>"""
confirm_href = site + "/auth/confirm?token_hash={{ .TokenHash }}&type=email&next={{ .RedirectTo }}"
recovery_href = site + "/auth/confirm?token_hash={{ .TokenHash }}&type=recovery&next=" + site + "/auth/update-password"
patch = {
    "smtp_host": os.environ["SMTP_HOST"].strip(),
    "smtp_port": os.environ["SMTP_PORT"].strip(),
    "smtp_user": os.environ["GMAIL_ADDRESS"].strip(),
    "smtp_pass": os.environ["GMAIL_APP_PASSWORD"].strip(),
    "smtp_admin_email": os.environ["GMAIL_ADDRESS"].strip(),
    "smtp_sender_name": os.environ["SMTP_SENDER_NAME"].strip(),
    "rate_limit_email_sent": int(os.environ["SMTP_MAX_PER_HOUR"]),
    "mailer_subjects_confirmation": "Confirm your Mahayuddh account",
    "mailer_templates_confirmation_content": page(
        "Confirm your email to start practising with your squad.",
        "Confirm your email",
        'You signed up for Mahayuddh with <span style="color:#ededef">{{ .Email }}</span>. Confirm it\'s you and your first battle is ready.',
        "Confirm email", confirm_href, "Confirm email",
        "Didn't sign up? Ignore this email and no account is activated."),
    "mailer_subjects_recovery": "Reset your Mahayuddh password",
    "mailer_templates_recovery_content": page(
        "Your password reset link. It works once and expires in 1 hour.",
        "Reset your password",
        'Someone asked to reset the password for <span style="color:#ededef">{{ .Email }}</span>. If that was you, choose a new one.',
        "Choose a new password", recovery_href, "Password reset",
        "Didn't ask? Ignore this email and your password stays the same."),
    "mailer_autoconfirm": False,
    "security_manual_linking_enabled": True,
}
json.dump(patch, open(sys.argv[1], "w"))
PY
  api PATCH "$body"; rm -f "$body"
  if [[ "$API_STATUS" == "200" ]]; then
    printf '  %s✓ Supabase accepted the change%s\n' "$GREEN" "$RESET"
  else
    warn "Supabase answered HTTP $API_STATUS:"
    python3 -I -c "import sys; print('  ', open(sys.argv[1]).read()[:400])" "$API_BODY_FILE"
    SKIPPED+=("Supabase PATCH failed (HTTP $API_STATUS); re-run")
  fi
  rm -f "$API_BODY_FILE"
else
  SKIPPED+=("email settings not applied; re-run and apply")
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Check"
api GET
if [[ "$API_STATUS" == "200" ]]; then
  python3 -I - "$API_BODY_FILE" <<'PY'
import json, sys
c = json.load(open(sys.argv[1]))
print(f"  SMTP:            {c.get('smtp_host') or 'built-in'} as {c.get('smtp_user') or '-'}")
print(f"  Confirm email:   {'OFF' if c.get('mailer_autoconfirm') else 'ON'}")
print(f"  Manual linking:  {'ON' if c.get('security_manual_linking_enabled') else 'OFF'}")
print(f"  Templates point at /auth/confirm: {'/auth/confirm' in (c.get('mailer_templates_confirmation_content') or '')}")
PY
fi
rm -f "$API_BODY_FILE"
say ""
say "Test it: on $SITE_URL/login use 'Forgot password?' with your own address."
say "The email should arrive from $GMAIL_ADDRESS within a minute; its link should"
say "open the new-password form, on your phone too."
pause

finish
